407→      && Number.isFinite(usage.totalCachedInputTokens)
408→      && Number.isFinite(usage.totalOutputTokens)
409→      && Number.isFinite(usage.lastInputTokens)
410→      && Number.isFinite(usage.lastCachedInputTokens)
411→      && Number.isFinite(usage.lastOutputTokens)
412→  )
