415→function isSameCodexUsageSnapshot(a: CodexUsageInfo | null, b: CodexUsageInfo | null): boolean {
416→  return Boolean(
417→    hasValidCodexUsageSnapshot(a)
418→      && hasValidCodexUsageSnapshot(b)
419→      && a.totalInputTokens === b.totalInputTokens
420→      && a.totalCachedInputTokens === b.totalCachedInputTokens
421→      && a.totalOutputTokens === b.totalOutputTokens
422→      && a.lastInputTokens === b.lastInputTokens
423→      && a.lastCachedInputTokens === b.lastCachedInputTokens
424→      && a.lastOutputTokens === b.lastOutputTokens
425→  )
