428→function accumulateCodexFooterTokens(
429→  current: { input: number; output: number },
430→  usage: CodexUsageInfo,
431→  previous: CodexUsageInfo | null,
432→): { input: number; output: number } {
433→  if (!hasValidCodexUsageSnapshot(usage) || isSameCodexUsageSnapshot(usage, previous)) {
